INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('lemurian-sea-dart-interceptor', 1, 'Ionic Charge Imbalancer', '5D6 M.D. per blast', 1, '1,500 feet (457 m) in all environments; double on or within one mile (1.6 km) of a ley line or nexus point', 'Each blast counts as one melee attack/action.', 'Effectively unlimited as long as the vessel is charged.', NULL, 'Ion pulses channelled through the drive; fires 360 degrees without turning the craft. Assault and anti-aircraft.'),
  ('lemurian-sea-dart-interceptor', 2, 'Symbiotic Living Torpedoes', '2D6 M.D. warning shot, 4D6 M.D. full strength, or 1D4x10+2 M.D. power attack (uses both of the torpedo''s attacks). Suicide detonation: 2D4x10 M.D.', 1, 'About 4,000 feet (1,219 m) per melee round; chases a target up to 4 miles (6.4 km)', 'Launching one counts as one of the pilot''s melee attacks; the torpedo then has two attacks of its own before returning.', 'Two re-useable Living Torpedoes.', '+3 to strike', 'Living fish launched from the belly; water and underwater targets only, and the pilot can retarget them. Each has 25 M.D.C., top speed 120 mph (192 km/104 knots), +5 automatic dodge, Prowl 50%, and does not show on sonar or radar. Returns at half speed and recharges in one minute (4 melee rounds). A suicide order is obeyed 01-90% and destroys the torpedo. Double damage to the undead. If the vessel is gone it waits 1D4+2 days, then swims off.'),
  ('lemurian-sea-dart-interceptor', 3, 'Sea Dart Symbiote and Repairs', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. With the craft stopped (hovering or landed) the symbiote remoulds the hull, restoring 2D6 M.D.C. each melee round. Its own body regains 2D6 M.D.C. every 24 hours; magical healing also works on it.'),
  ('lemurian-sea-dart-interceptor', 4, 'Sensor System (psychic)', NULL, 0, '1,000 feet (305 m); double along ley lines', NULL, NULL, NULL, 'Not a weapon. No conventional sensors: the symbiote uses Empathy (4), Presence Sense (4), See the Invisible (4), Sense Dimensional Anomaly (4), Sense Time (2), Sixth Sense (2) and Telepathy (4). Base I.S.P. 1D6x10+33.'),
  ('lemurian-cloud-shell', 1, 'Stonecaster Gun (Nose Weapon)', 'Sedimentary: 4D6 M.D. to everything in an 8 foot (2.4 m) blast radius. Igneous: 5D6 M.D. on impact and 2D6 M.D. for the next 1D4 melee rounds. Metamorphic: 1D4x10+4 M.D.', 1, '4,000 feet (1,219 m), half underwater', 'Each shot counts as one melee attack.', '60 rounds; regenerates two rounds per hour. Payload and regeneration double inside a ley line triangle such as the Demon Sea; payload quadruples on a ley line, at a nexus or at a Lemurian stone pyramid.', NULL, 'Fixed forward. Stone Magic makes the rock chips it fires. Anti-submarine/anti-sea monster, secondarily anti-ship.'),
  ('lemurian-cloud-shell', 2, 'Ionic Charge Imbalancer', '1D4x10 M.D. per blast', 1, '1,500 feet (457 m) in all environments; double on or within one mile of a ley line or nexus point', 'Each blast counts as one melee attack/action.', 'Effectively unlimited as long as the vessel is charged.', NULL, 'The drive''s ionising effect boosted into a lightning-like stream; fires 360 degrees without turning the craft. Assault and anti-aircraft.'),
  ('lemurian-cloud-shell', 3, 'Symbiotic Living Torpedoes', '2D6 M.D. warning shot, 4D6 M.D. full strength, or 1D4x10+2 M.D. power attack (uses both of the torpedo''s attacks). Suicide detonation: 2D4x10 M.D.', 1, 'About 4,000 feet (1,219 m) per melee round; chases a target up to 4 miles (6.4 km)', 'One at a time or in volleys of two or four; a launch or volley counts as one of the pilot''s melee attacks. Each torpedo then has two attacks of its own.', 'Six re-useable Living Torpedoes.', '+3 to strike', 'Same as the Sea Dart Interceptor''s apart from rate of fire and payload: living fish, water targets only, 25 M.D.C., 120 mph, +5 automatic dodge, Prowl 50%, invisible to sonar and radar, one minute to recharge aboard, suicide order obeyed 01-90%, double damage to the undead.'),
  ('lemurian-cloud-shell', 4, 'Cloud Shell Symbiote and Repairs', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. With the craft stopped (hovering, floating, on land or on the sea floor) the symbiote remoulds the hull, restoring 2D6 M.D.C. each melee round. Its own body regains 3D6 M.D.C. every 24 hours; magical healing also works on it.'),
  ('lemurian-cloud-shell', 5, 'Sensor System (psychic)', NULL, 0, '1,000 feet (305 m); double along ley lines', NULL, NULL, NULL, 'Not a weapon. As the Sea Dart: Empathy (4), Presence Sense (4), See the Invisible (4), Sense Dimensional Anomaly (4), Sense Time (2), Sixth Sense (2) and Telepathy (4). Base I.S.P. 2D4x10+28.'),
  ('lemurian-cloud-wind', 1, 'Ionic Charge Imbalancer', '1D6x10 M.D. per blast', 1, '1,500 feet (457 m) in all environments; double on or within one mile (1.6 km) of a ley line or nexus point', 'Each blast counts as one melee attack.', 'Effectively unlimited as long as the vessel is charged.', NULL, 'Lightning bolts from the larger drive; fires 360 degrees without turning the craft. Assault and anti-aircraft.'),
  ('lemurian-cloud-wind', 2, 'Symbiotic Living Torpedoes', '2D6 M.D. warning shot, 4D6 M.D. full strength, or 1D4x10+2 M.D. power attack (uses both of the torpedo''s attacks). Suicide detonation: 2D4x10 M.D.', 1, 'About 4,000 feet (1,219 m) per melee round; chases a target up to 4 miles (6.4 km)', 'One at a time or in volleys of two or four; a launch or volley counts as one of the pilot''s melee attacks. Each torpedo then has two attacks of its own.', '12 re-useable Living Torpedoes.', '+3 to strike', 'Same as the Sea Dart Interceptor''s apart from rate of fire and payload: living fish, water targets only, 25 M.D.C., 120 mph, +5 automatic dodge, Prowl 50%, invisible to sonar and radar, one minute to recharge aboard, suicide order obeyed 01-90%, double damage to the undead.'),
  ('lemurian-cloud-wind', 3, 'Mini-Missile Launchers (2)', 'Varies with missile type; plasma is favored: 1D6x10 M.D. to a 15 foot (4.6 m) radius', 1, 'One mile (1.6 km)', 'One at a time or in volleys of 2, 4, 6 or 8.', '36 total mini-missiles, 16 in each wing (as printed).', NULL, 'One conventional human-tech launcher hidden in each wing, used from the water surface against aircraft, and from the air against land or air targets. Anti-aircraft/flyers, secondarily anti-missile and defense.'),
  ('lemurian-cloud-wind', 4, 'Seaweed Chaff', NULL, 0, 'Fills a 60 foot (18.3 m) diameter sphere', NULL, '8 seaweed bundles.', NULL, 'Defensive; works only underwater or on the surface. Swimmers touching the cloud take the Seaweed Bloom spell''s penalties and propellers are likely to foul and stall. A torpedo of any size (mini to long range) passing through has a 01-70% chance to detonate or lose lock; if one in a volley detonates, 01-90% all the rest do too, otherwise only 1D4x10% of them. An onboard Biomancer can enlarge the cloud with Seaweed Bloom.'),
  ('lemurian-cloud-wind', 5, 'Troops', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Carried troops can leave the vehicle while it is moving, at a reasonable speed, to join a fight or attack.'),
  ('lemurian-cloud-wind', 6, 'Cloud Wind Symbiote and Repairs', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. With the craft stopped (hovering, floating, on land or on the sea floor) the symbiote remoulds the hull, restoring 3D6 M.D.C. each melee round. Its own body regains 3D6 M.D.C. every 24 hours; magical healing also works on it.'),
  ('lemurian-cloud-wind', 7, 'Sensor System (psychic)', NULL, 0, '1,000 feet (305 m); double along ley lines', NULL, NULL, NULL, 'Not a weapon. As the Sea Dart: Empathy (4), Presence Sense (4), See the Invisible (4), Sense Dimensional Anomaly (4), Sense Time (2), Sixth Sense (2) and Telepathy (4), plus Read Dimensional Portal (6). Base I.S.P. 2D4x10+40.'),
  ('lemurian-wave-shadow-submarine', 1, 'Main Gun Stonecaster Cannon (1)', 'Sedimentary: 6D6 M.D. to everything in a 20 foot (6.1 m) blast radius. Igneous: 1D6x10 M.D. on impact and 3D6 M.D. more for the next 1D4 melee rounds. Metamorphic: 2D6x10 M.D.', 1, '4,000 feet (1,219 m), half underwater', 'Each shot counts as one melee attack/action of its dedicated gunner (typically 4-5 attacks per melee round).', '100 shells; regenerates two rounds per hour. Payload and regeneration double inside a ley line triangle such as the Demon Sea; payload triples on a ley line, at a nexus or at a Lemurian stone pyramid.', NULL, 'Oversized stonecaster firing enchanted mini-boulders from a turret: 360 degree rotation, 90 degree arc up and down. Anti-ship, secondarily anti-submarine/anti-sea monster.'),
  ('lemurian-wave-shadow-submarine', 2, 'Standard Stonecaster Cannons (2)', 'Sedimentary: 5D6 M.D. to everything in an 8 foot (2.4 m) blast radius. Igneous: 1D4x10 M.D. on impact and 2D6 M.D. more for the next 1D4 melee rounds. Metamorphic: 2D4x10 M.D.', 1, '4,000 feet (1,219 m), half underwater', 'Each shot counts as one melee attack/action.', '100 rounds each; regenerates two rounds per hour. Payload and regeneration double inside a ley line triangle such as the Demon Sea; payload triples on a ley line, at a nexus or at a Lemurian stone pyramid.', NULL, 'Secondary guns, one gunner each: 360 degree rotation, 45 degree arc up and down. Anti-submarine/anti-sea monster, secondarily anti-ship.'),
  ('lemurian-wave-shadow-submarine', 3, 'Symbiotic Living Torpedoes', '2D6 M.D. warning shot, 4D6 M.D. full strength, or 1D4x10+2 M.D. power attack (uses both of the torpedo''s attacks). Suicide detonation: 2D4x10 M.D.', 1, 'About 4,000 feet (1,219 m) per melee round; chases a target up to 4 miles (6.4 km)', 'One at a time or in volleys of two or four; a launch or volley counts as one melee attack. Each torpedo then has two attacks of its own.', '16 total: eight re-useable Living Torpedoes in the launcher on each side.', '+3 to strike', 'Fired by the captain or second officer. Otherwise the same as the Sea Dart Interceptor''s: living fish, water targets only, 25 M.D.C., 120 mph, +5 automatic dodge, Prowl 50%, invisible to sonar and radar, one minute to recharge aboard, suicide order obeyed 01-90%, double damage to the undead.'),
  ('lemurian-wave-shadow-submarine', 4, 'Underwater Proximity Ionic Charge Imbalancer', '5D6 M.D. per discharge', 1, '100 feet (30.5 m); double on a ley line', 'Each blast/discharge counts as one melee attack of its dedicated gunner.', 'Effectively unlimited as long as the vessel is charged.', NULL, 'Close defense: the drive floods nearby water with ion energy, against boarders and small subs latching on. Defense, secondarily anti-submarine/anti-sea monster.'),
  ('lemurian-wave-shadow-submarine', 5, 'Seaweed Chaff', NULL, 0, NULL, NULL, '8 seaweed bundles.', NULL, 'The same system as the Cloud Wind''s: a 60 foot (18.3 m) seaweed cloud that hampers swimmers as the Seaweed Bloom spell, fouls propellers, and gives torpedoes a 01-70% chance to detonate or lose lock (01-90% the rest of a volley follows, else 1D4x10% of it).'),
  ('lemurian-wave-shadow-submarine', 6, 'Troops', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Carried troops can leave the sub while it is moving, at a reasonable speed, to join a fight or attack.'),
  ('lemurian-wave-shadow-submarine', 7, 'Wave Shadow Symbiotes and Repairs', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon (headed ''Shadow Wave'' in the book). Each section is repaired by its own symbiote with the sub at 10 mph (16 km) or less, floating still or on the sea floor: 3D6 M.D.C. each melee round. Its own body regains 3D6 M.D.C. every 24 hours; magical healing also works on it.'),
  ('lemurian-wave-shadow-submarine', 8, 'Sensor System (psychic)', NULL, 0, '1,000 feet (305 m); double along ley lines', NULL, NULL, NULL, 'Not a weapon. As the Sea Dart: Empathy (4), Presence Sense (4), See the Invisible (4), Sense Dimensional Anomaly (4), Sense Time (2), Sixth Sense (2) and Telepathy (4), plus Read Dimensional Portal (6). Base I.S.P. 2D4x10+40.'),
  ('lemurian-scuttler-submersible-tank', 1, 'Stonecaster Cannon', 'Sedimentary: 5D6 M.D. to everything in an 8 foot (2.4 m) blast radius. Igneous: 1D4x10 M.D. on impact and 2D6 M.D. more for the next 1D4 melee rounds. Metamorphic: 2D4x10 M.D.', 1, '4,000 feet (1,219 m), half underwater', 'Each shot counts as one melee attack/action.', '100 rounds; regenerates two rounds per hour. Payload and regeneration double inside a ley line triangle such as the Demon Sea; payload triples on a ley line, at a nexus or at a Lemurian stone pyramid.', NULL, 'Main gun with its own gunner: 360 degree rotation, 45 degree arc up and down. Sedimentary rounds shatter into a blast, igneous rounds are lava pellets that keep burning, metamorphic rounds are dense armor-piercers. Anti-submarine/anti-sea monster, secondarily anti-ship.'),
  ('lemurian-scuttler-submersible-tank', 2, 'TK Defense', '1D6 M.D. per punch; Power TK-punch 2D6 M.D. (counts as two melee attacks); restrained TK-punch 3D6 S.D.C.', 1, '50 feet (15.2 m) in all environments', 'Each TK attack counts as one melee attack/action of the pilot.', 'Effectively unlimited.', '+1 to strike and parry giant-sized opponents; +1 to block/hit a volley of incoming missiles or torpedoes', 'Experimental telekinetic ''invisible hands'' that punch, block and parry; usable only against opponents 10 feet (3 m) tall or larger, never man-sized targets, and not as a standing wall or shield. Primary purpose is listed as an inertial dampening system. A blocked missile or torpedo volley has a 01-33% chance to explode on impact or veer off, and a deflected volley may strike an ally or cause collateral damage.'),
  ('lemurian-scuttler-submersible-tank', 3, 'Spined Fins', '1D6 M.D. to attackers climbing or holding on (they may attempt to dodge); 3D6 M.D. to sea serpents, squid and giants gripping the tank in jaws, hands or tentacles', 1, NULL, NULL, NULL, NULL, 'A pair of internal spined ridges that extend through the armor and sweep in wide circles like a buzz saw, to throw off melee attackers and anything trying to swallow the tank.'),
  ('lemurian-scuttler-submersible-tank', 4, 'Scuttler Symbiote and Repairs', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. With the tank stopped (hovering, floating, on land or on the sea floor) the symbiote remoulds the hull, restoring 2D6 M.D.C. each melee round. Its own body regains 3D6 M.D.C. every 24 hours; magical healing also works on it.'),
  ('lemurian-scuttler-submersible-tank', 5, 'Sensor System (psychic)', NULL, 0, '1,000 feet (305 m); double along ley lines', NULL, NULL, NULL, 'Not a weapon. As the Sea Dart: Empathy (4), Presence Sense (4), See the Invisible (4), Sense Dimensional Anomaly (4), Sense Time (2), Sixth Sense (2) and Telepathy (4), plus TK Defense at no extra I.S.P. cost. Base I.S.P. 1D6x10+33.'),
  ('lemurian-wind-seer', 1, 'Ionic Charge Imbalancer', '2D6 M.D. per blast', 1, '500 feet (152 m) in all environments; double on or within one mile of a ley line or nexus point', 'Each blast counts as one melee attack/action.', 'Effectively unlimited as long as the vessel is charged.', NULL, 'Electric bolts drawn from the drive; fires 360 degrees. Assault and anti-aircraft.'),
  ('lemurian-wind-seer', 2, 'Wind Seer Symbiote and Repairs', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. With the drone stopped (hovering or landed) the symbiote remoulds the shell, restoring 2D6 M.D.C. each melee round. Its own body regains 2D6 M.D.C. every 24 hours; magical healing also works on it.'),
  ('lemurian-wind-seer', 3, 'Sensor System (psychic)', NULL, 0, '1,000 feet (305 m); double along ley lines', NULL, NULL, NULL, 'Not a weapon. Empathy (4), Mind Block (4), Presence Sense (4), Read Dimensional Portal (6), See the Invisible (4), Sense Dimensional Anomaly (4), Sense Evil (2), Sense Magic (3), Sense Time (2), Sixth Sense (2) and Telepathy (4). Base I.S.P. 2D4x10+36.'),
  ('lemurian-moai-stone-guardian', 1, 'Breath Attack', '4D6 M.D. against supernatural evil, or 4D6 S.D.C. against mortal foes', 1, '100 feet (30.5 m)', NULL, NULL, NULL, 'A jet of steam from the mouth. Like every Moai attack it does double damage to Necromancers, animated dead, vampires and all undead.'),
  ('lemurian-moai-stone-guardian', 2, 'Eye Beams', 'Small Moai: 4D6 M.D. vs supernatural evil, 1D6x10 M.D. vs greater supernatural evil and deities, 3D6 M.D. vs other M.D.C. opponents. Large: 6D6 M.D., 2D6x10 M.D., 4D6 M.D. Giant: 1D6x10 M.D., 3D6x10 M.D., 6D6 M.D. Against mortal and S.D.C. targets: 1D6 to 5D6 S.D.C., set in 1D6 steps.', 1, '3,000 feet (914 m)', 'Four as an automaton, or the pilot''s number of attacks; each eye blast counts as one attack.', 'Effectively unlimited.', NULL, 'Energy blasts from the eyes. Double damage to Necromancers, animated dead, vampires and all undead.'),
  ('lemurian-moai-stone-guardian', 3, 'Hand to Hand Combat', 'Punches, kicks and head butts by Supernatural P.S. (Small 27, Large 37, Giant 47); double damage to greater supernatural beings', 1, NULL, 'Automaton: four attacks per melee round. Piloted: the pilot''s attacks +2.', NULL, 'Automaton vs supernatural evil: +5 Perception, +3 initiative, +6 strike, +4 parry, +2 dodge, +4 pull punch, +2 roll with impact; halve (round down) vs mortals. Piloted: pilot''s own bonuses plus +2 Perception (double vs supernatural evil), +2 initiative, +2 strike and parry, +3 pull punch, +2 roll with impact, +4 save vs Horror Factor, +3 save vs possession and mind control.', 'The Moai itself is immune to Horror Factor and to every kind of possession or outside control, though its pilot is not. Piloted, it answers at the speed of thought and uses the pilot''s attacks and moves. Double damage to the undead as with all its attacks.'),
  ('lemurian-moai-stone-guardian', 4, 'Ley Line Healing', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Needs rest mode on a ley line, nexus, ley line triangle or Easter Island. If the main body is at zero but the head has any M.D.C. left, it regrows 1D6x10 main body M.D.C. per hour and reactivates after the first 10; head, then limbs, heal only once the main body is whole. A head destroyed on a ley line, nexus or Easter Island reforms after 48 hours, one piece per hour, then heals the same way; destroyed elsewhere it is lost unless the pieces go back to Easter Island for a Stone Master ritual.'),
  ('lemurian-moai-stone-guardian', 5, 'Resistance to Magic', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Immune to possession and to magic fire, heat and lava. Magic cold does half damage. Electricity, lightning, other magic energy, physical attacks, missiles and high-tech weapons do full damage.'),
  ('lemurian-moai-stone-guardian', 6, 'Spell Casting Through the Moai (Voice of the Moai)', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. One rider at a time, usually the pilot, speaks through the statue in a deep baritone and may cast most spoken spells and Whale Songs through it: spell range doubled, spell damage +50%. Barred: rituals, Temporal Magic, Create Zombie, Animate and Control Dead, Metamorphosis, disguise, concealment and illusion magic, Necromancy, Demon Magic, Soulmancy and any dark magic; no Techno-Wizard devices, magic items, wards or circles, and nothing needing a delicate touch.'),
  ('lemurian-moai-stone-guardian', 7, 'Senses', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Hearing and touch equal a human''s; smell about twice as keen. Full color supernatural vision: can pick out a bird 6 miles (9.6 km) off on the horizon, sees in total darkness to one mile (1.6 km), and sees the invisible, including Astral Travelers and fragmented essences of Alien Intelligences.'),
  ('lemurian-moai-stone-guardian', 8, 'Sense Ley Line Location', NULL, 0, '30 miles (48 km)', NULL, NULL, NULL, 'Not a weapon. Lets the Moai find ley lines to recharge.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('lemurian-moai-stone-guardian', 9, 'Sense the Supernatural', NULL, 0, '100 miles (160 km)', NULL, NULL, NULL, 'Not a weapon. Instantly senses supernatural evil and begins a deep ''singing'' moan, audible island-wide yet carrying roughly one mile (1.6 km) over the water; on its master''s order it then hunts the intruder. Asked, the statues standing guard on Easter Island can name the kind of menace, its rough position within 1,000 miles (1,600 km) and its heading; great gatherings of evil are felt out to 5,000 miles (8,000 km). No evil supernatural force has got closer to the island than 10 miles (16 km).');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 7 machines are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicles WHERE slug IN ('lemurian-sea-dart-interceptor', 'lemurian-cloud-shell', 'lemurian-cloud-wind', 'lemurian-wave-shadow-submarine', 'lemurian-scuttler-submersible-tank', 'lemurian-wind-seer', 'lemurian-moai-stone-guardian');
SELECT 'their 43 locations are in' AS assertion, count(*) AS got, 43 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('lemurian-sea-dart-interceptor', 'lemurian-cloud-shell', 'lemurian-cloud-wind', 'lemurian-wave-shadow-submarine', 'lemurian-scuttler-submersible-tank', 'lemurian-wind-seer', 'lemurian-moai-stone-guardian');
SELECT 'their 41 weapon entries are in' AS assertion, count(*) AS got, 41 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('lemurian-sea-dart-interceptor', 'lemurian-cloud-shell', 'lemurian-cloud-wind', 'lemurian-wave-shadow-submarine', 'lemurian-scuttler-submersible-tank', 'lemurian-wind-seer', 'lemurian-moai-stone-guardian');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('lemurian-sea-dart-interceptor', 'lemurian-cloud-shell', 'lemurian-cloud-wind', 'lemurian-wave-shadow-submarine', 'lemurian-scuttler-submersible-tank', 'lemurian-wind-seer', 'lemurian-moai-stone-guardian') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~175-lemuria-vehicles.sql');
